package io.github.daily3minutes.audio

import android.content.Context
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import io.github.daily3minutes.backup.*
import io.github.daily3minutes.data.*
import kotlinx.coroutines.*
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import java.io.*
import java.util.UUID
import java.util.zip.*

/** Fixtures contain generated bytes only. No microphone or production directory is accessed. */
@RunWith(AndroidJUnit4::class)
class VoiceArchiveInstrumentedTest {
    private val context: Context get() = ApplicationProvider.getApplicationContext()
    private lateinit var root: File
    private val databases = mutableListOf<DailyDatabase>()
    @Before fun setup() { root = File(context.cacheDir, "synthetic-archive-${UUID.randomUUID()}").apply { mkdirs() } }
    @After fun cleanup() { databases.forEach { it.close() }; root.deleteRecursively() }
    private fun library(name: String): VoiceLibrary {
        val db = Room.inMemoryDatabaseBuilder(context, DailyDatabase::class.java).build().also { databases += it }
        return VoiceLibrary(db, File(root, name), { error("No microphone in synthetic archive tests") })
    }
    private val bytes = byteArrayOf(0, 0, 0, 24, 102, 116, 121, 112) + "synthetic-archive-audio".toByteArray()
    private suspend fun note(library: VoiceLibrary, date: String = "2026-10-24", question: Int = 1): VoiceNote {
        val id = UUID.randomUUID().toString(); val file = File(library.directory, "$id.m4a").apply { writeBytes(bytes) }
        return VoiceNote(id, date, question, 1500, 100, file.length(), VoiceLibrary.digest(file)).also { library.db.voices().insert(it) }
    }
    private fun manager(lib: VoiceLibrary) = VoiceArchiveManager(lib, DailyRepository(lib.db), root)

    @Test fun fullBackupRestoresAllTextAudioIdentityAndDefaultDateConflicts() = runBlocking {
        val source = library("source"); val from = DailyRepository(source.db)
        from.save("2026-10-24", "Synthetic learning", "Synthetic uncertainty", "Synthetic priority")
        val clip = note(source)
        val out = ByteArrayOutputStream(); manager(source).export(out)
        val target = library("target"); val to = DailyRepository(target.db); val archives = manager(target)
        archives.parse(ByteArrayInputStream(out.toByteArray())).use { preview ->
            assertEquals(1, archives.preview(preview).added)
            archives.apply(preview, false)
            assertEquals("Synthetic learning", to.get(clip.date)!!.learned)
            assertEquals("Synthetic uncertainty", to.get(clip.date)!!.unclear)
            assertEquals("Synthetic priority", to.get(clip.date)!!.nextPriority)
            assertEquals(clip, target.db.voices().get(clip.id))
            assertArrayEquals(bytes, target.file(clip).readBytes())
        }
        to.save(clip.date, "Keep new local wording", "", "")
        archives.parse(ByteArrayInputStream(out.toByteArray())).use { preview ->
            assertEquals(listOf(clip.date), archives.preview(preview).conflicts)
            archives.apply(preview, false)
            assertEquals("Keep new local wording", to.get(clip.date)!!.learned)
            archives.apply(preview, true)
            assertEquals("Synthetic learning", to.get(clip.date)!!.learned)
            assertEquals(1, target.db.voices().all().size)
        }
    }

    @Test fun audioOnlyDatesArePreviewedAndRestoredWithoutInventingWrittenAnswers() = runBlocking {
        val source = library("source"); val clip = note(source)
        val out = ByteArrayOutputStream(); manager(source).export(out)
        val target = library("target"); val archives = manager(target)
        archives.parse(ByteArrayInputStream(out.toByteArray())).use { preview ->
            assertEquals(1, archives.preview(preview).added); archives.apply(preview, false)
        }
        assertNull(DailyRepository(target.db).get(clip.date))
        assertEquals(clip, target.db.voices().all().single())
    }

    @Test fun rejectedPathsAndChangedAudioNeverModifyExistingRecords() = runBlocking {
        val lib = library("target"); val repo = DailyRepository(lib.db)
        repo.save("2026-10-24", "Keep synthetic local entry", "", "")
        fun zip(name: String, data: ByteArray): ByteArray = ByteArrayOutputStream().also { output ->
            ZipOutputStream(output).use { it.putNextEntry(ZipEntry(name)); it.write(data); it.closeEntry() }
        }.toByteArray()
        for (name in listOf("../escape.m4a", "/absolute.m4a", "recordings/../../escape", "unexpected.json")) {
            assertTrue(runCatching { manager(lib).parse(ByteArrayInputStream(zip(name, bytes))) }.isFailure)
        }
        val source = library("source"); val clip = note(source)
        val output = ByteArrayOutputStream(); manager(source).export(output)
        val changed = ByteArrayOutputStream()
        ZipInputStream(ByteArrayInputStream(output.toByteArray())).use { input -> ZipOutputStream(changed).use { dest ->
            while (true) { val entry = input.nextEntry ?: break; dest.putNextEntry(ZipEntry(entry.name))
                val data = input.readBytes(); dest.write(if (entry.name.endsWith(".m4a")) data + 1.toByte() else data); dest.closeEntry() }
        } }
        assertTrue(runCatching { manager(lib).parse(ByteArrayInputStream(changed.toByteArray())) }.isFailure)
        assertEquals("Keep synthetic local entry", repo.get(clip.date)!!.learned)
        assertTrue(lib.db.voices().all().isEmpty())
        assertFalse(File(root.parentFile, "escape.m4a").exists())
    }

    @Test fun failedDatabaseApplyRollsBackTextMetadataAndNewAudioFiles() = runBlocking {
        val source = library("source"); note(source)
        DailyRepository(source.db).save("2026-10-24", "Incoming synthetic", "", "")
        val output = ByteArrayOutputStream(); manager(source).export(output)
        val target = library("target"); val repo = DailyRepository(target.db)
        repo.save("2026-10-24", "Original synthetic", "", "")
        target.db.openHelper.writableDatabase.execSQL("CREATE TRIGGER synthetic_reject BEFORE INSERT ON daily_records BEGIN SELECT RAISE(ABORT, 'synthetic failure'); END")
        val archives = manager(target)
        archives.parse(ByteArrayInputStream(output.toByteArray())).use { preview ->
            assertTrue(runCatching { archives.apply(preview, true) }.isFailure)
        }
        assertEquals("Original synthetic", repo.get("2026-10-24")!!.learned)
        assertTrue(target.db.voices().all().isEmpty())
        assertTrue(target.directory.listFiles().orEmpty().isEmpty())
    }

    @Test fun explicitRecordingDeletionKeepsAllWrittenAnswers() = runBlocking {
        val lib = library("target"); val clip = note(lib)
        DailyRepository(lib.db).save(clip.date, "Keep text", "Question", "Priority")
        lib.delete(clip)
        assertNull(lib.db.voices().get(clip.id)); assertFalse(lib.file(clip).exists())
        assertEquals("Keep text", DailyRepository(lib.db).get(clip.date)!!.learned)
    }

    @Test fun leavingForegroundStopsASyntheticCaptureAndKeepsItsOriginalQuestion() = runBlocking {
        val db = Room.inMemoryDatabaseBuilder(context, DailyDatabase::class.java).build().also { databases += it }
        var stopped = false; var released = false
        val lib = VoiceLibrary(db, File(root, "capture"), { object : VoiceCapture {
            override fun start(file: File, onLimit: () -> Unit) { file.writeBytes(bytes) }
            override fun stop() { stopped = true }
            override fun release() { released = true }
        } })
        lib.setForeground(true); lib.start("2026-10-24", 2)
        withTimeout(5000) { while (lib.session.value == null) delay(10) }
        lib.setForeground(false)
        withTimeout(5000) { while (lib.session.value != null) delay(10) }
        assertTrue(stopped && released)
        assertEquals(2, db.voices().all().single().question)
        assertEquals("2026-10-24", db.voices().all().single().date)
        lib.start("2026-10-25", 0); delay(50)
        assertNull(lib.session.value)
    }

    @Test fun completeBackupFinishesPendingCaptureAndDeletingItsDayRemovesAudioMetadata() = runBlocking {
        val db = Room.inMemoryDatabaseBuilder(context, DailyDatabase::class.java).build().also { databases += it }
        val lib = VoiceLibrary(db, File(root, "capture-export"), { object : VoiceCapture {
            override fun start(file: File, onLimit: () -> Unit) { file.writeBytes(bytes) }
            override fun stop() = Unit
            override fun release() = Unit
        } })
        lib.setForeground(true); lib.start("2026-10-24", 0)
        withTimeout(5000) { while (lib.session.value == null) delay(10) }
        val output = ByteArrayOutputStream(); manager(lib).export(output)
        assertNull(lib.session.value)
        manager(lib).parse(ByteArrayInputStream(output.toByteArray())).use { assertEquals(1, it.manifest.recordings.size) }
        val clip = db.voices().all().single()
        DailyRepository(db).delete(clip.date)
        lib.pruneOrphans()
        assertTrue(db.voices().all().isEmpty()); assertFalse(lib.file(clip).exists())
    }

    @Test fun generatedAacSurvivesBackupAndPlaysToCompletionWithoutMicrophone() = runBlocking {
        val source = library("encoded-source")
        val id = UUID.randomUUID().toString()
        val file = File(source.directory, "$id.m4a")
        SyntheticAac.write(file)
        val clip = VoiceNote(id, "2026-10-24", 0, 1000, 100, file.length(), VoiceLibrary.digest(file))
        source.db.voices().insert(clip)
        val output = ByteArrayOutputStream(); manager(source).export(output)
        val target = library("encoded-target"); val archives = manager(target)
        archives.parse(ByteArrayInputStream(output.toByteArray())).use { archives.apply(it, false) }
        val done = java.util.concurrent.CountDownLatch(1)
        var player: android.media.MediaPlayer? = null
        var error = false
        val instrumentation = androidx.test.platform.app.InstrumentationRegistry.getInstrumentation()
        try {
            instrumentation.runOnMainSync {
                player = android.media.MediaPlayer().apply {
                    setDataSource(target.file(clip).absolutePath); prepare(); setVolume(0f, 0f)
                    setOnCompletionListener { done.countDown() }
                    setOnErrorListener { _, _, _ -> error = true; done.countDown(); true }
                    start()
                }
            }
            assertTrue("Synthetic AAC playback did not finish", done.await(8, java.util.concurrent.TimeUnit.SECONDS))
            assertFalse("Synthetic AAC failed to decode", error)
        } finally { instrumentation.runOnMainSync { player?.release() } }
    }
}
